/* Устанавливаем фон из твоей картинки */
body {
    background: url("https://psv4.userapi.com/s/v1/d/78xbUNB5Q4OBVP6Wb4zznkVl6QdcwY2oKlQcnjQW4O8zK3-eZiaiwlD-mV4Qwpy1cHZVDpbVHY4DtVqPoOXI-AhrZfzZ_irz2Ze6FoRRqLCHf5gDnYm_oQ/razm.png") no-repeat center center fixed;
    background-size: cover;
}

/* Делаем все фоны прозрачными */
* {
    background-color: transparent !important;
    color: #ffffff !important; /* Чтобы текст был виден */
}

/* Убираем тени и рамки */
* {
    box-shadow: none !important;
    border: none !important;
}
